export const isLanguage = value => value === "en" || value === "el";

export function translate(key, language) {
  return strings[key][language === "el" ? 1 : 0];
}

export function translatePage(language) {
  const attributes = { i18nLabel: "aria-label", i18nTitle: "title", i18nPlaceholder: "placeholder",
    i18nAlt: "alt", i18nContent: "content" };
  for (const element of document.querySelectorAll("[data-i18n]")) {
    element.textContent = translate(element.dataset.i18n, language);
  }
  for (const [key, attribute] of Object.entries(attributes)) {
    const selector = key.replace(/[A-Z]/g, letter => "-" + letter.toLowerCase());
    for (const element of document.querySelectorAll(`[data-${selector}]`)) {
      element.setAttribute(attribute, translate(element.dataset[key], language));
    }
  }
  document.documentElement.lang = language;
}
